import json, hashlib, os
man = json.load(open('inputs/manifest.json'))
ok, bad, missing = 0, [], []
for f in man['files']:
    p = os.path.join('inputs', f['path'])
    if not os.path.exists(p):
        missing.append(f['path']); continue
    h = hashlib.sha256(open(p,'rb').read()).hexdigest()
    if h != f['sha256']:
        bad.append((f['path'], h))
    else:
        ok += 1
print(f"total={len(man['files'])} ok={ok} mismatch={len(bad)} missing={len(missing)}")
for b in bad: print("MISMATCH", b)
for m in missing: print("MISSING", m)
EOF","description":"Verify SHA-256 of all input files against manifest"}

